const rows = $input.all();
if (!rows || rows.length === 0) {
  throw new Error('No product rows found in the sheet. Check the filter or sheet tab name.');
}
const required = ['Name', 'Family', 'Product_Image_URL__c'];
const first = rows[0].json;
const missing = required.filter(col => !(col in first));
if (missing.length > 0) {
  throw new Error(`Missing required columns: ${missing.join(', ')}. Check your sheet headers.`);
}
return rows.map(r => ({
  json: {
    ...r.json,
    _validatedAt: new Date().toISOString(),
    _totalRows: rows.length,
  }
}));

