const allItems = $input.all();
const synced = allItems.filter(i => i.json?.record?.id).length;
const errors = allItems.filter(i => i.json?.Error === 'Yes').length;
return [{
  json: {
    totalProcessed: allItems.length,
    synced,
    errors,
    completedAt: new Date().toISOString(),
  }
}];

